/* @autogenerated */
package net.civeira.phylax.features.oauth.delegatelogin.domain.provider;

import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.delegatelogin.domain.DelegatedAccessExternalProvider.RequestInfo;
import net.civeira.phylax.features.oauth.delegatelogin.domain.DelegatedRequestDetails;
import net.civeira.phylax.features.oauth.delegatelogin.domain.FederatedUser;

class GoogleDelegatedAccessProviderUnitTest {

  @Test
  @DisplayName("the identity is the Google sub, never the display name")
  void test_identity_is_sub() throws Exception {
    FederatedUser user = GoogleDelegatedAccessProvider.toUser(
        "{\"sub\":\"1234\",\"name\":\"admin\",\"email\":\"a@gmail.com\",\"email_verified\":true}")
        .orElseThrow();
    Assertions.assertEquals("1234", user.getSubject());
    Assertions.assertEquals("a@gmail.com", user.getEmail());
    Assertions.assertTrue(user.isEmailVerified());
  }

  @Test
  @DisplayName("email_verified counts only when it is true")
  void test_email_verified_strict() throws Exception {
    Assertions.assertFalse(GoogleDelegatedAccessProvider
        .toUser("{\"sub\":\"1\",\"email\":\"a@b.c\",\"email_verified\":\"false\"}").orElseThrow()
        .isEmailVerified());
    Assertions.assertFalse(GoogleDelegatedAccessProvider
        .toUser("{\"sub\":\"1\",\"email\":\"a@b.c\"}").orElseThrow().isEmailVerified());
    Assertions.assertTrue(GoogleDelegatedAccessProvider
        .toUser("{\"sub\":\"1\",\"email\":\"a@b.c\",\"email_verified\":\"true\"}").orElseThrow()
        .isEmailVerified());
  }

  @Test
  @DisplayName("without sub there is no identity")
  void test_without_sub() throws Exception {
    Assertions.assertTrue(GoogleDelegatedAccessProvider
        .toUser("{\"email\":\"a@b.c\",\"email_verified\":true}").isEmpty());
  }

  @Test
  @DisplayName("PKCE S256 challenge matches RFC 7636 appendix B")
  void test_pkce_vector() {
    Assertions.assertEquals("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM",
        GoogleDelegatedAccessProvider.challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"));
  }

  @Test
  @DisplayName("the authorization request carries state and PKCE")
  void test_request_params() {
    GoogleDelegatedAccessProvider provider =
        new GoogleDelegatedAccessProvider("google", "client", "secret", false);
    RequestInfo info = provider.request(AuthRequest.builder().tenant("acme").build(),
        DelegatedRequestDetails.builder().externalUrl("https://cb").state("st")
            .codeVerifier("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk").build());
    Map<String, String> params = info.getParams();
    Assertions.assertEquals("st", params.get("state"));
    Assertions.assertEquals("S256", params.get("code_challenge_method"));
    Assertions.assertEquals("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM",
        params.get("code_challenge"));
    Assertions.assertEquals("https://cb", params.get("redirect_uri"));
  }

  @Test
  @DisplayName("a response with error or without code yields no identity")
  void test_error_response() {
    GoogleDelegatedAccessProvider provider =
        new GoogleDelegatedAccessProvider("google", "client", "secret", false);
    DelegatedRequestDetails details = DelegatedRequestDetails.builder().build();
    AuthRequest request = AuthRequest.builder().tenant("acme").build();
    Assertions.assertTrue(provider
        .authenticate(request, details, Map.of("error", new String[] {"access_denied"})).isEmpty());
    Assertions.assertTrue(provider.authenticate(request, details, Map.of()).isEmpty());
  }
}
